/**
 * The live's numbers, each the ONE copy (docs/wiki/services/lives.md).
 *
 * Clients carry none of them: `GET /api/lives/limits` publishes them, for the reason
 * `reel.constants.ts` gives - an installed APK keeps whatever it was built with.
 */

/** The live key: 32 random bytes, generated by the broadcaster's client, carried as 64 hex chars. */
export const LIVE_KEY_HEX_RE = /^[0-9a-f]{64}$/;

/**
 * The largest sealed segment the server accepts, in bytes. A segment is a few seconds of 720p at
 * ~2.5 Mb/s (about 1 MB for 3 s), so 4 MiB is generous and stays half the 8 MiB request-body
 * invariant of the media session routes (media-streaming-upload.md, section 3.2).
 */
export const LIVE_SEGMENT_MAX_BYTES = 4 * 1024 * 1024;

/**
 * Q5 (live.md): after this long with no segment, the live is ENDED by the sweep, durably
 * (`endReason = 'dropped'`). What viewers show meanwhile ("reconnecting") is theirs to decide from
 * `lastSegmentAt` and `serverNow` in the manifest; the END is this row's state, never a client timer.
 * To be confirmed on the WP-L1 bench.
 */
export const LIVE_RECONNECT_WINDOW_MS = 60_000;

/** How many segments one manifest answer lists at most - a viewer polls from its last index. */
export const LIVE_MANIFEST_WINDOW = 10;

/**
 * HOW MANY OF THE NEWEST SEGMENTS A RUNNING LIVE KEEPS in the store: twice the manifest window
 * (owner, 2026-10-31: nothing outlives what viewers can still ask for). A manifest names at most
 * {@link LIVE_MANIFEST_WINDOW} segments ending at the newest, so the newest ten are all a viewer is ever
 * TOLD about; the other ten are the margin for a viewer that fetched its manifest just before a trim
 * and is still downloading. A viewer polls every second and a segment is ~2 s, so ten more segments
 * are ~20 s of margin against a download of a segment of about 1 MB; and a viewer further behind than
 * its buffer policy allows jumps to the newest (`livePlayer`, backlog) instead of walking the past.
 * Every segment is self-contained, so a viewer never needs an older one for its init.
 *
 * Stored bytes per live are therefore bounded by this many segments of at most
 * {@link LIVE_SEGMENT_MAX_BYTES} (plus the few still waiting for a retried delete), whatever its duration.
 */
export const LIVE_RETAINED_SEGMENTS = 2 * LIVE_MANIFEST_WINDOW;

/**
 * THE LONGEST A REPLAY GOES BACK (owner, 2026-11-09, D1 of docs/wiki/live-replays.md): a live that
 * keeps a replay keeps the segments whose `createdAt` is at most this far behind its NEWEST segment's,
 * the database's own times - a 10-hour live keeps its last three hours. Never fewer than
 * {@link LIVE_RETAINED_SEGMENTS}, which the viewers of the running live still need.
 */
export const LIVE_REPLAY_MAX_MS = 3 * 60 * 60 * 1000;

/**
 * THE SHORTEST LIVE THAT BECOMES A REPLAY (owner, 2026-11-09, D4): `lastSegmentAt - startedAt`, the
 * database's clock. A false start shows nothing.
 */
export const LIVE_REPLAY_MIN_MS = 30_000;

// How long a replay is kept after its live's END is no constant since 2026-11-14: the admin setting
// `platform_config.retention_live_replay_days` (3 days by default, core migration 025), read at the
// replay's publication and written once into `posts."expiresAt"` (`common/retention-settings.ts`).

/** How many segments one page of `GET /api/lives/:id/replay` lists; the client asks `from=nextFrom`. */
export const LIVE_REPLAY_PAGE = 200;

/**
 * The replays' TOTAL cap by default, in GB of 10^9 bytes (owner, 2026-11-09, D5) - a config value:
 * `LIVE_REPLAY_TOTAL_MAX_GB` overrides it ({@link liveReplayTotalMaxBytes}).
 */
export const LIVE_REPLAY_TOTAL_MAX_GB_DEFAULT = 20;

/** How long a cap eviction stays on record for the admin storage panel, in days. */
export const LIVE_REPLAY_EVICTION_KEEP_DAYS = 30;

/**
 * The replays' total cap in bytes, from `LIVE_REPLAY_TOTAL_MAX_GB` (a positive number of GB, a
 * fraction allowed) or {@link LIVE_REPLAY_TOTAL_MAX_GB_DEFAULT}. THROWS on a value that is set and is
 * not a positive number: a typo must stop the service at boot, never silently mean "no cap" or "0".
 */
export function liveReplayTotalMaxBytes(
  raw: string | undefined = process.env.LIVE_REPLAY_TOTAL_MAX_GB
): number {
  if (raw === undefined || raw.trim() === '') return LIVE_REPLAY_TOTAL_MAX_GB_DEFAULT * 1e9;
  const gb = Number(raw.trim());
  if (!Number.isFinite(gb) || gb <= 0) {
    throw new Error(`LIVE_REPLAY_TOTAL_MAX_GB must be a positive number of GB, got "${raw}"`);
  }
  return Math.round(gb * 1e9);
}

/** The most segments one trim pass deletes: bounds a pass that catches up after a media-service outage. */
export const LIVE_TRIM_BATCH = 50;

/**
 * The shortest segment the server expects, in ms. The plan cuts segments of a few seconds (about
 * 1 MB for 3 s); one a second is a third of that, so a client that catches up after a reconnect is
 * never refused for it.
 */
export const LIVE_SEGMENT_MIN_DURATION_MS = 1_000;

/**
 * How many segments a live may hold ahead of its age. Segment `index` is accepted only while
 * `index < LIVE_SEGMENT_BURST + floor(elapsed / LIVE_SEGMENT_MIN_DURATION_MS)`, elapsed being the
 * database's `now() - startedAt`: a COUNT held in durable state (the index IS the number of segments
 * taken) against the live's own age, so a broadcaster cannot send faster than one segment a second
 * on average, whatever its retries do. Refused with 429 `LIVE_SEGMENT_TOO_FAST`.
 */
export const LIVE_SEGMENT_BURST = 15;

/** How many lives one account may START in a rolling hour (`live_starts`); 429 `LIVE_START_RATE`. */
export const LIVE_STARTS_PER_HOUR = 6;

/**
 * At most one ANNOUNCED live per association in this many hours (WP-1b, docs/wiki/engagement.md L16):
 * an association's live reaches its whole audience, so ending and restarting must not ring it again.
 * Read against `associations."lastLiveAnnouncedAt"` in segment 0's claim (`LivesService.confirm`).
 */
export const LIVE_ASSOCIATION_ANNOUNCE_INTERVAL_HOURS = 6;

/** The rolling window of {@link LIVE_STARTS_PER_HOUR}, and how long a `live_starts` row is kept. */
export const LIVE_START_WINDOW_MS = 60 * 60_000;

/**
 * How long social-service waits for media-service to store one segment. NO DATABASE CONNECTION IS
 * HELD MEANWHILE (the index is reserved in a committed step first, `LivesService.ingest`).
 */
export const LIVE_STORE_TIMEOUT_MS = 30_000;

/**
 * How old a reservation must be before another ingest may take it over, or the purge may ignore it:
 * the store's timeout plus a margin, so the HTTP call that made it cannot still be waiting in THIS
 * service. A Garage write that outlives the call is the orphan the reaper takes (lives.md).
 */
export const LIVE_RESERVATION_TTL_MS = LIVE_STORE_TIMEOUT_MS + 5_000;

/**
 * How many segment ingests one social-service instance runs at once; the next is refused with 503
 * `LIVE_INGEST_BUSY`. Well below the database pool (10): an ingest holds no connection across the
 * store, but each one holds up to 4 MiB in memory and a media-service request.
 */
export const LIVE_INGEST_MAX_CONCURRENT = 4;

/**
 * THE HOST'S USABLE EGRESS, in bits per second: the floor of the ~90-107 Mb/s aggregate measured
 * out of production on 443 (realtime-media-feasibility.md, sections 4 and 2a, two separate hours).
 * Every viewer of every live is one more copy out of this ONE link - nginx's cache saves the app
 * and the store, never a byte of it (live.md, option C). A MEASUREMENT FROM ONE OUTSIDE CLIENT, to
 * be replaced by the DSI's figure (Q3) or a campus-side measurement when either exists.
 */
export const LIVE_HOST_EGRESS_BPS = 90_000_000;

/**
 * The share of {@link LIVE_HOST_EGRESS_BPS} lives may take. The link also carries production's own
 * traffic, dev, Le Cercle and the co-tenant sites of a host we do not own; 0.8 leaves a fifth of it
 * to everything else. A planning figure.
 */
export const LIVE_EGRESS_SHARE = 0.8;

/**
 * What one viewer costs the uplink, in bits per second: the MEASURED mean of the WP-L1 bench on the
 * platform that produces more (Chrome/Android, 2.89-3.06 Mb/s against a 2.5 Mb/s target;
 * device-readings-calls-live-2026-10-18.md). Sized on the heavier broadcaster, so a live from an
 * iPhone (~1.45 Mb/s) leaves headroom rather than the reverse.
 */
export const LIVE_VIEWER_BITRATE_BPS = 3_000_000;

/**
 * THE VIEWER CAP OF THE HOST (L8 as the plan resolved it: "a cap set by the host's uplink"):
 * floor(90 Mb/s x 0.8 / 3 Mb/s) = 24 seats, across EVERY live at once, since they share the link.
 * Seat N+1 is refused 503 `LIVE_FULL` (lives.md, "The viewer cap"). The broadcaster takes none.
 */
export const LIVE_VIEWER_CAP = Math.floor(
  (LIVE_HOST_EGRESS_BPS * LIVE_EGRESS_SHARE) / LIVE_VIEWER_BITRATE_BPS
);

/**
 * How long a seat is held after the viewer's last key read or manifest poll. A viewer polls every
 * segment (a few seconds), so 30 s is ten polls missed: wrong too SHORT, a watching viewer loses its
 * seat to the next one in; wrong too LONG, a viewer that vanished without `DELETE .../seat` (a
 * crash, a lost network) holds a seat that long. The leave route is the proof; this is only the
 * bound on a viewer that could not send it.
 */
export const LIVE_SEAT_LEASE_MS = 30_000;

/** Why a live ended - the `endReason` column. `cut`: staff ended it (WP-L8, `POST /api/lives/:id/cut`). */
export type LiveEndReason = 'broadcaster' | 'dropped' | 'erased' | 'cut';

/**
 * THE REASON CODES OF A STAFF CUT - the report reasons of `content_reports`
 * (`frontend/src/lib/moderation/reasons.ts`), so a moderator answers a report in the vocabulary it
 * was filed in. A code, never a sentence: the broadcaster's client words it in its own language.
 */
export const LIVE_CUT_REASONS = ['spam', 'harassment', 'inappropriate', 'other'] as const;
export type LiveCutReason = (typeof LIVE_CUT_REASONS)[number];

/** The longest free text a moderator may attach to a cut (the mute reason's bound). */
export const LIVE_CUT_DETAILS_MAX = 500;

/** One day, the unit the moderation durations below are decided in. */
const DAY_MS = 24 * 60 * 60_000;

/**
 * How long a cut is KEPT (`live_cuts`): 90 days, the owner's decision of 2026-10-20 (register row
 * C20). Deleted by the live sweep past it; an account erasure deletes the account's at once.
 */
export const LIVE_CUT_RETENTION_MS = 90 * DAY_MS;

/**
 * THE STRIKE LADDER COUNTS THE CUTS STILL ON RECORD (owner, 2026-10-20): a rolling window equal to
 * the cut's retention, so an abuse older than it is forgotten. ONE number, not two that agree today:
 * a cut the ladder still counts is a cut that is still kept. Every count reads `"cutAt"` against the
 * database clock with this window, so a prune running late never makes a forgotten cut count.
 */
export const LIVE_STRIKE_WINDOW_MS = LIVE_CUT_RETENTION_MS;

/**
 * The strike from which a cut SUSPENDS the right to broadcast (owner, 2026-10-20: the 1st abuse is a
 * warning and the cut, the 2nd a suspension). A cut's strike is fixed when it is recorded
 * (`live_cuts.strike`, 1 + the other cuts on record then), so a later prune of an older cut never
 * lifts a suspension it caused.
 */
export const LIVE_SUSPENSION_FROM_STRIKE = 2;

/** How long a suspension lasts, from the cut that caused it: 30 days (owner, 2026-10-20). */
export const LIVE_SUSPENSION_MS = 30 * DAY_MS;

/**
 * The cuts on record from which STAFF MAY WITHDRAW the right to broadcast (owner, 2026-10-20: the
 * 3rd abuse, "decided by staff"). Never automatic: the 3rd cut suspends, as the 2nd does, and
 * `withdrawalDue` tells a moderator the decision is theirs to take.
 */
export const LIVE_WITHDRAWAL_FROM_CUTS = 3;

/**
 * THE HARD BOUND ON A REPORTED CHAT LINE (owner, 2026-10-20, WP-L8b): kept until its report is
 * handled, and NEVER longer than this, handled or not - an unhandled report would otherwise keep a
 * member's words for ever. Erased by the live sweep, from `keptAt` (the report's time).
 */
export const LIVE_CHAT_REPORT_MAX_KEEP_MS = 90 * DAY_MS;

/**
 * THE RESPONSE COMMITMENT TO THE STORES (owner, 2026-10-20): a live report (`live` or `live_chat`)
 * is answered within 24 hours ON WORKING DAYS. A pending report whose WORKING age passes this is
 * named at `error` by the hourly `[LIVE_REPORT_AGE]` report (`LiveReportAgeScheduler`).
 */
export const LIVE_REPORT_RESPONSE_WORKING_MS = DAY_MS;

/**
 * The zone whose Saturdays and Sundays are not working days for {@link LIVE_REPORT_RESPONSE_WORKING_MS}:
 * the school's. Public holidays are NOT left out (no calendar of them exists here), so the alarm can
 * fire on a bank holiday a day early - early, never late.
 */
export const LIVE_REPORT_WORKING_ZONE = 'Europe/Paris';

/**
 * THE VERSION OF THE RULES A MEMBER ACCEPTS BEFORE BROADCASTING (L11). A start is refused 403
 * `LIVE_RULES_NOT_ACCEPTED` unless the member's recorded acceptance (`live_rules_acceptances`) is at
 * least this version, or the start itself carries `acceptedRulesVersion` equal to it - which records
 * it. Raise it when the rules' TEXT changes, so every member accepts the new text once. Version 2
 * (2026-10-21): the sheet shows the posts' publication rules (owner, 2026-10-20), not the four
 * live-specific lines of version 1.
 */
export const LIVE_RULES_VERSION = 2;

/**
 * THE LONGEST CHAT MESSAGE, in UTF-16 code units of plain text (WP-L6, C11). The server never sees
 * the text - it is sealed with the live key - so this is the CLIENT's bound, published here so an
 * installed build reads it rather than carries it; the server bounds the sealed size below.
 */
export const LIVE_CHAT_MESSAGE_MAX_CHARS = 300;

/**
 * HOW MANY ACCOUNTS ONE CHAT LINE MAY MENTION (owner, 2026-11-09): the first `LIVE_CHAT_MENTIONS_MAX`
 * of those a line declares are told, the rest are dropped by the server; `LIVE_CHAT_MENTIONS_DECLARED_MAX`
 * bounds the list a client may declare at all (a longer one is 400 `LIVE_MESSAGE_INVALID`).
 */
export const LIVE_CHAT_MENTIONS_MAX = 5;
export const LIVE_CHAT_MENTIONS_DECLARED_MAX = 20;

/**
 * A person is told of a mention by the SAME author on the SAME live at most once per this window,
 * counted from the rows themselves (`live_chat_messages."mentionedUserIds"`), never a clock held in
 * memory - the rule of every other limit of the chat (C6).
 */
export const LIVE_CHAT_MENTION_WINDOW_MS = 60_000;

/** The AES-GCM overhead of a sealed message: a 12-byte IV and a 16-byte tag (C12). */
export const LIVE_CHAT_SEAL_OVERHEAD_BYTES = 12 + 16;

/**
 * The largest sealed message the server stores: the overhead plus 300 UTF-16 units at most 3 UTF-8
 * bytes each (a pair of units is a 4-byte character, under 6), so 928 bytes.
 */
export const LIVE_CHAT_SEALED_MAX_BYTES =
  LIVE_CHAT_SEAL_OVERHEAD_BYTES + 3 * LIVE_CHAT_MESSAGE_MAX_CHARS;

/**
 * THE LONGEST TEXT A CHAT-LINE REPORT MAY HAND OVER, in UTF-8 bytes (WP-L8b): whatever the largest
 * sealed line the server STORES can hold, so every line a viewer can see is reportable - not the
 * client composer's 300 characters, which an older or another client need not have applied
 * (review of #2172). A UTF-16 unit is at least one UTF-8 byte, so it bounds the units too.
 */
export const LIVE_CHAT_REPORT_TEXT_MAX_BYTES =
  LIVE_CHAT_SEALED_MAX_BYTES - LIVE_CHAT_SEAL_OVERHEAD_BYTES;

/** The smallest: the overhead and one byte of text - an empty message is not a message. */
export const LIVE_CHAT_SEALED_MIN_BYTES = LIVE_CHAT_SEAL_OVERHEAD_BYTES + 1;

/**
 * How many messages one account may post on one live in {@link LIVE_CHAT_RATE_WINDOW_MS} (C6),
 * counted from its rows under the live's row lock, by the database clock. 429 `LIVE_MESSAGE_TOO_FAST`.
 */
export const LIVE_CHAT_MESSAGES_PER_WINDOW = 3;

/** The rolling window of {@link LIVE_CHAT_MESSAGES_PER_WINDOW}. */
export const LIVE_CHAT_RATE_WINDOW_MS = 5_000;

/** What a viewer's FIRST poll (no `messagesAfter`) receives: the newest messages, at most this many (C13). */
export const LIVE_CHAT_BACKLOG = 50;

/** The most messages one poll answers after its cursor; the rest come with the next poll. */
export const LIVE_CHAT_PAGE = 100;

/**
 * THE ARRIVAL LINES' RATE RULE (owner, 2026-11-07, "X a rejoint" visible to every viewer,
 * rate-limited): a poll names at most this many arrivals; the rest of what it read is folded into a
 * count ("et N autres"). A COUNT PER POLL, never a clock: the same arrivals give the same answer.
 */
export const LIVE_ARRIVALS_PER_POLL = 3;

/** The most arrivals one poll reads after its cursor (above the viewer cap, so one poll reads all). */
export const LIVE_ARRIVALS_PAGE = 50;

/** The arrivals log keeps this many newest entries per live; the dedupe set is the live's own. */
export const LIVE_ARRIVALS_LOG_MAX = 100;

/** How long the arrival keys live without a take: a live's own length, deleted at its purge. */
export const LIVE_ARRIVALS_TTL_MS = 6 * 60 * 60 * 1000;

/**
 * THE FIVE FLOATING REACTIONS (owner, 2026-10-20, superseding C8): ❤️ like (heart), 😂 laugh,
 * 👏 clap (bravo), 🔥 fire, 🐤 canari (the canary chick). No sad, no angry. ASCII wire names; the
 * client draws the Noto picture. A burst naming an older kind (`love`, `happy`) is 400
 * `LIVE_REACTION_INVALID` - dev builds only, so nothing in the field breaks.
 */
export const LIVE_REACTION_KINDS = ['like', 'laugh', 'clap', 'fire', 'canari'] as const;

/** One of {@link LIVE_REACTION_KINDS}. */
export type LiveReactionKind = (typeof LIVE_REACTION_KINDS)[number];

/**
 * The step reactions are summed over (C7): a burst falls in window floor(age / 2 s) of its live, and
 * the poll answers one sum per kind per window. Also the rolling window of the two rates below.
 */
export const LIVE_REACTION_WINDOW_MS = 2_000;

/** How many bursts one account may send per {@link LIVE_REACTION_WINDOW_MS} (C6). */
export const LIVE_REACTION_BURSTS_PER_WINDOW = 2;

/** How many taps one account may make per {@link LIVE_REACTION_WINDOW_MS}: five a second (C6). */
export const LIVE_REACTION_TAPS_PER_WINDOW = 10;

/** The most bursts one poll sums after its cursor; the rest come with the next poll. */
export const LIVE_REACTION_PAGE = 500;

/**
 * THE LONGEST LIVE TITLE, in characters (Unicode code points - what PostgreSQL's `varchar(80)` and
 * `char_length` count): owner, 2026-11-07. The title is OPTIONAL, entered on the launch screen and
 * editable while on air; without one the card reads "X est en direct" as before. Plain text the
 * server stores and serves, like a post's text (lives.md, "Titles and the preview").
 */
export const LIVE_TITLE_MAX_CHARS = 80;

/**
 * THE LARGEST SEALED PREVIEW IMAGE ("poster") the server accepts, in bytes (owner, 2026-11-07: a
 * refreshed still image on the feed card). The broadcaster sends a JPEG 480 px wide at quality 0.7
 * (a 480 x 854 portrait frame is tens of kB), sealed under the poster key (HKDF of the live key); 256 KiB leaves room for a
 * busy frame and is a sixteenth of a segment. Refused 413 `LIVE_POSTER_TOO_LARGE` above it.
 */
export const LIVE_POSTER_MAX_BYTES = 256 * 1024;

/**
 * THE ONE PERIOD OF THE PREVIEW, in ms (review of #3135: two cadences, 10 s sent and 15 s read,
 * left a third of the posters unseen). BOTH ends read it from the limits:
 *
 * - the BROADCASTER sends a poster every `round(previewPeriodMs / segment length)` segments (8 with
 *   its 2 s segments), counted on the durable segment index, never on a timer - no segment, no
 *   poster, and a paused camera leaves the last image with its age;
 * - a FEED CARD on screen, in a visible page, re-reads `GET /api/lives` once per period, so each
 *   poster sent is the one the next read names.
 *
 * Served, never compiled into a client, so the load can be shaped without a release. It is a cost
 * knob and nothing else: wrong, the picture is staler or the list read more often; nothing is
 * decided from it.
 */
export const LIVE_PREVIEW_PERIOD_MS = 16_000;

/**
 * THE SHORTEST GAP BETWEEN TWO STORED POSTERS of one live, in ms, decided on the row's `posterAt`
 * (the database's clock): a poster sooner than this is 429 `LIVE_POSTER_TOO_FAST`. Half the
 * {@link LIVE_PREVIEW_PERIOD_MS}: never met by an honest broadcaster, and a dishonest one is bounded
 * at 7.5 stores a minute.
 */
export const LIVE_POSTER_MIN_INTERVAL_MS = LIVE_PREVIEW_PERIOD_MS / 2;

/**
 * WHAT A POSTER TYPICALLY WEIGHS, in bytes - a planning figure (a 480 x 854 JPEG at quality 0.7 is
 * tens of kB), to be replaced by the reading owed on both phones. It sizes the budget below.
 */
export const LIVE_POSTER_TYPICAL_BYTES = 48 * 1024;

/**
 * THE PREVIEW'S EGRESS BOUND PER ADDRESS, in bits per second (review of #3135) - a PER-ADDRESS bound,
 * NOT a host budget. Posters are served by their OWN nginx location and zones
 * (`/api/media/public/live-poster/`), so a card reader never spends the segments' per-address quota;
 * that location bounds ONE address at `limit_conn` x `limit_rate` = this number -
 * `live-segments-route.test.mjs` recomputes it, and that the live share plus one address's bound fits
 * the host's uplink.
 *
 * Nothing caps posters host-wide: every zone is keyed on the client address, as the segments' are,
 * and the segments' global bound is the SEAT cap, which a poster does not take. Host-wide, posters
 * cost readers-on-screen x ~24.6 kb/s (one {@link LIVE_POSTER_TYPICAL_BYTES} poster per
 * {@link LIVE_PREVIEW_PERIOD_MS}), which reaches the 18 Mb/s the live share leaves near 730 readers at
 * once (lives.md, "What the preview costs", says why no global cap was added). What this bound buys:
 * ~325 card readers behind ONE campus address before a 429 - which costs a card a stale picture,
 * never a seated viewer a segment.
 */
export const LIVE_POSTER_EGRESS_PER_ADDRESS_BPS = 8_000_000;

/** The numbers as the API serves them. */
export function liveLimits(): {
  segmentMaxBytes: number;
  reconnectWindowMs: number;
  manifestWindow: number;
  segmentMinDurationMs: number;
  segmentBurst: number;
  startsPerHour: number;
  viewerCap: number;
  seatLeaseMs: number;
  rulesVersion: number;
  chatMessageMaxChars: number;
  chatSealedMaxBytes: number;
  chatMessagesPerWindow: number;
  chatRateWindowMs: number;
  chatBacklog: number;
  reactionKinds: readonly LiveReactionKind[];
  reactionWindowMs: number;
  reactionBurstsPerWindow: number;
  reactionTapsPerWindow: number;
  strikeWindowMs: number;
  suspensionMs: number;
  titleMaxChars: number;
  posterMaxBytes: number;
  previewPeriodMs: number;
} {
  return {
    segmentMaxBytes: LIVE_SEGMENT_MAX_BYTES,
    reconnectWindowMs: LIVE_RECONNECT_WINDOW_MS,
    manifestWindow: LIVE_MANIFEST_WINDOW,
    segmentMinDurationMs: LIVE_SEGMENT_MIN_DURATION_MS,
    segmentBurst: LIVE_SEGMENT_BURST,
    startsPerHour: LIVE_STARTS_PER_HOUR,
    viewerCap: LIVE_VIEWER_CAP,
    seatLeaseMs: LIVE_SEAT_LEASE_MS,
    rulesVersion: LIVE_RULES_VERSION,
    chatMessageMaxChars: LIVE_CHAT_MESSAGE_MAX_CHARS,
    chatSealedMaxBytes: LIVE_CHAT_SEALED_MAX_BYTES,
    chatMessagesPerWindow: LIVE_CHAT_MESSAGES_PER_WINDOW,
    chatRateWindowMs: LIVE_CHAT_RATE_WINDOW_MS,
    chatBacklog: LIVE_CHAT_BACKLOG,
    reactionKinds: LIVE_REACTION_KINDS,
    reactionWindowMs: LIVE_REACTION_WINDOW_MS,
    reactionBurstsPerWindow: LIVE_REACTION_BURSTS_PER_WINDOW,
    reactionTapsPerWindow: LIVE_REACTION_TAPS_PER_WINDOW,
    strikeWindowMs: LIVE_STRIKE_WINDOW_MS,
    suspensionMs: LIVE_SUSPENSION_MS,
    titleMaxChars: LIVE_TITLE_MAX_CHARS,
    posterMaxBytes: LIVE_POSTER_MAX_BYTES,
    previewPeriodMs: LIVE_PREVIEW_PERIOD_MS,
  };
}
